-- GENERATED by `wfj generate` from data/quest/quest-0091.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [91208] = { "Fare i conti con la realtà", "Trova il Frightened Paladin ad ⟦Deathknell=Albamorta⟧.", "Non tutti i nostri confratelli paladini che risorgono si adattano in fretta alla nostra nuova realtà. Alcuni faticano ad accettare di essere ora, in un certo senso, proprio ciò che hanno combattuto per tutta la vita.\n\nSpesso a queste persone bastano un gesto gentile e un orecchio comprensivo. Purtroppo, molti altri diventano subito violenti. Trova la paladina spaventata fuggita sulle colline subito a ovest di questa cappella. Tendile una mano in amicizia. Riconducila alla Luce, se puoi.", nil, "Purtroppo non sono pochi i nostri fratelli e sorelle che cadono in una follia simile dopo essere risorti. Per quanto ogni anima dei Reietti sia preziosa, a volte il meglio che possiamo fare è concedere una fine pulita a chi non riesce ad adattarsi.\n\nDirò una preghiera alla Luce per lei. Grazie per aver fatto ciò che andava fatto, {name}.", 0x369056a8, 0x4e575d59, 0xf3aba797, nil, 0x08cfc7d1, "...m." },
  [91209] = { "Continua l'addestramento", "Segui la strada verso est fuori da ⟦Deathknell=Albamorta⟧ fino alla città di Brill. Fai rapporto a Shari Stilwell per continuare l'addestramento.", "Lordaeron non sarà più quella di un tempo, ma la nostra casa ha ancora bisogno di protezione da ogni genere di minaccia, ed è ora che tu esca ad affrontare il mondo. La tua prossima tappa è la città di Brill, nel cuore delle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Va' a incontrare Shari Stilwell. Si occuperà del tuo addestramento.\n\nUn ultimo consiglio prima di partire: fa' molta attenzione, da paladin<o/a> in viaggio per le terre dei Reietti. Molti al servizio della Dama Oscura diffidano di noi e della nostra vicinanza alla Luce.", nil, "Benvenut<o/a> tra noi, {class}. È sempre incoraggiante vedere altri dei nostri percorrere queste terre. Qui a Brill in molti hanno bisogno dell'aiuto di avventurieri come te. Cerca lavoro e diventa più forte nella Luce. Torna da me ogni volta che ti serve addestramento.\n\nQuando avrai dato prova di te a me e alla gente di Brill, ti darò indicazioni per la prossima tappa del tuo viaggio.\n\nVa' con la Luce, {class}.", 0x4085cde1, 0x85d93d6b, 0xaa599bfa, nil, 0x5e8d646c, "...m." },
  [91282] = { "Una seconda casa", "Trova la fortezza di Bandarion Keep e fai rapporto a Breton Samuels.", "È incoraggiante vedere i miei fratelli e sorelle appena risorti prosperare come hai fatto tu. Ma è solo attraverso la comunità e la fede condivisa che possiamo davvero realizzare il nostro pieno potenziale, ed è per questo che abbiamo iniziato a fondare un nuovo ordine di paladini proprio qui a Tirisfal.\n\nSe vuoi saperne di più, visita il nostro monastero ai margini dei Whispering Woods. Si chiama Bandarion Keep. Si trova sulle alture appena a nord-ovest della ⟦Solliden Farmstead=Cascina dei Solliden⟧: difficile non vederlo.", nil, "Un'altra recluta? Benvenuto a Tyr's Watch, fratello.", 0x323b0ccf, 0x66582164, 0x5716314a, nil, 0xed54e9da, "...m." },
  [91285] = { "Murloc alle porte", "Uccidi $N1 Vile Fin Attacker e $N2 Vile Fin Seer, poi torna a riferire a Breton Samuels.", "Di solito saremmo più ospitali con i nuovi arrivati, ma al momento abbiamo un piccolo problema di murloc.\n\nUna tribù di murloc usava la fortezza per deporre le uova. Ci danno problemi da quando ci siamo trasferiti qui e li abbiamo cacciati, ma ora la situazione sta sfuggendo di mano. Sembri <uno/una> che ha visto un po' d'azione. Pensi di poterci aiutare a respingere qualcuno di questi parassiti? Li troverai appostati sulle alture lungo la strada a est e negli accampamenti intorno al lago a ovest.", nil, "Grazie dell'aiuto. Non credo che questo fermerà del tutto gli attacchi, ma spero che li rallenti un po'. È già abbastanza difficile ricostruire questo posto senza un murloc che cerca di piantarti una lancia nella schiena.", 0x7785ffc2, 0x7b21c67e, 0x12268215, nil, 0x273fdfba, "...m." },
  [91294] = { "Un giro della fortezza", "Parla con gli abitanti di Bandarion Keep.", "Ora che la minaccia immediata degli attacchi dei murloc è sotto controllo, ti consiglio di fare un giro della nostra roccaforte. Per ora non è granché, ma è casa nostra.\n\nQuando avrai finito di esplorare, cerca Danitha Morr, la nostra comandante. Ti aiuterà a sistemarti.\n\nSono davvero lieto di averti conosciuto, {name}. Che la Luce ti guidi.", nil, "Ti ha mandato Breton, eh? Ottimo.\n\nMi chiamo Danitha Morr, e sono quanto di più vicino a un comandante abbia questa fortezza. Se cerchi fratellanza tra coloro che restano ancora fedeli alla Luce, sei nel posto giusto.\n\nC'è molto lavoro da fare qui prima di poterci stabilire del tutto, e ti saremmo molto grati se volessi darci una mano.", 0x2887ca72, 0x410e846c, 0x44585301, nil, 0x902d5c25, "...m." },
  [91316] = { "Riparazioni", "Raccogli 12 Sturdy Lumber a Shadowvale, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Così lontano da ⟦Undercity=Sepulcra⟧, i rifornimenti sono un problema e abbiamo una grave carenza dei materiali da costruzione che servono a restaurare questa fortezza. Vorrei il tuo aiuto.\n\nIl villaggio in rovina di Shadowvale si trova nella Whispering Forest, appena a sud-ovest di qui. In uno degli edifici c'è una vecchia cantina usata per conservare ogni sorta di cose. Probabilmente laggiù ci sono materiali utilizzabili. Recupera ciò che puoi e torna da noi.", "Si dice che la posizione sia tutto. Questa fortezza arroccata su queste alture avrà anche un aspetto imponente, ma restare riforniti così lontano dalla civiltà si sta rivelando una bella sfida. Una svista spiacevole da parte nostra.", "Mi fa piacere che il tuo viaggio a Shadowvale abbia dato i suoi frutti. Più tardi manderò Breton e qualche altra nuova recluta a svuotare il resto della cantina e a recuperare ciò che è rimasto laggiù, al buio.", 0x2cfcd9f0, 0xb8282c24, 0x1518690b, 0xf3019911, 0xdf7b4d57, "....." },
  [91317] = { "I Tarnished", "Uccidi 8 Tarnished Drudge e 6 Tarnished Zealot, e raccogli la testa di Commander Rudolph Gelhardt nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Non tutti i paladini risorti si sono adattati bene alla nostra nuova esistenza, come forse hai già visto con i tuoi occhi. Alcuni si sono portati dietro i pregiudizi della vita, e continuano a usare violenza contro i loro compagni Reietti.\n\nAllo stato attuale la nostra gente diffida di noi, perché ricorda bene le persecuzioni inflitte dai vivi in nome della Luce, e questi attacchi non aiutano. Un certo numero di questi Tarnished si è stabilito a Shadowvale, a sud-ovest. Eliminali e portami la testa del loro capo.", "I Tarnished minacciano quel poco di benevolenza che abbiamo presso gli altri Reietti. Per quanto mi addolori incrociare le lame con quelli che erano nostri fratelli e sorelle, vanno fermati se il nostro giovane ordine vuole sopravvivere.", "Ottimo lavoro, {name}. Ogni volta che uno di questi Tarnished colpisce e uccide uno dei Reietti, per i nostri detrattori diventa ancora più facile alimentare la diffidenza verso noi paladini. Eliminarli aiuterà la nostra causa e consoliderà il nostro posto qui a Tirisfal.\n\nSospetto che ci vorrà molto tempo prima che i Reietti e l'Orda ci accolgano davvero. Potrebbero volerci anni... o forse decenni, ma il meglio che possiamo fare è continuare a dimostrare il nostro valore.", 0x56e9442f, 0x783dab34, 0x72df7fd8, 0x41fb5732, 0x6fd3aac2, "....." },
  [91723] = { "Strumenti delicati", "Uccidi 8 Kobold Geomancer nella ⟦Jasperlode Mine=Miniera Venarossa⟧, poi torna da Hamish Bergwort nella ⟦Tower of Azora=Torre di Azora⟧.", "Accidenti! Ogni volta che provo a calibrare questi delicati strumenti arcani, un'ondata di energia li sballa di nuovo.\nLe ondate sembrano arrivare da nord, dove quei coboldi primitivi praticano la loro rozza magia. Potresti eliminarne qualcuno, così posso continuare il mio lavoro?", nil, "Ben fatto, amico mio. Fammi riprovare con le calibrazioni...", 0x7065a8eb, 0xe5f80ea7, 0x91c5f081, nil, 0x8dec828f, "...m." },
  [91724] = { "Strumenti delicati", "Uccidi $N1 Defias Rogue Wizard presso il ⟦Stone Cairn Lake=Lago del Memoriale⟧, poi torna da Hamish Bergwort nella ⟦Tower of Azora=Torre di Azora⟧.", "Ci siamo quasi, e... per il Nether! Qualcosa disturba ancora i miei strumenti.\n\nÈ davvero frustrante, {name}. Ho sentito dire che i banditi della zona si esercitano con gli incantesimi vicino al ⟦Stone Cairn Lake=Lago del Memoriale⟧. Forse, se li fermi, queste interferenze cesseranno finalmente e potrò combinare qualcosa?", nil, "Sembra che tutto funzioni come si deve. Grazie, {name}.", 0x7065a8eb, 0xbccc5d13, 0xe7761ff1, nil, 0x4af97dcf, "...m." },
  [91725] = { "Materiali d'incantamento rubati", "Raccogli 5 Stolen Enchanting Supplies negli accampamenti degli gnoll intorno al ⟦Stone Cairn Lake=Lago del Memoriale⟧, poi torna da Blixie Fitzwink vicino alla ⟦Tower of Azora=Torre di Azora⟧.", "Mi ha mandato il maestro Theocritus a prendere dei materiali d'incantamento all'emporio, ma sulla via del ritorno un branco di gnoll mi ha teso un'imboscata!\n\nHo lasciato cadere il pacco e me la sono data a gambe, ma se torno senza, per punizione passerò settimane a ripulire dopo gli esperimenti di metamorfosi! Pensi di poter ritrovare i materiali per me?", "Hai trovato i materiali?", "Oh, che sollievo! Sembra che ci sia tutto. Grazie!", 0x78bd98c1, 0xeda8b676, 0xd9d3fe8f, 0x3a2cb041, 0x3db19b3c, "....." },
  [91732] = { "Buon acciaio", "Raccogli 4 Mining Tools nella ⟦Jasperlode Mine=Miniera Venarossa⟧, poi torna da Hagar Lowe al ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧.", "Dopo la guerra il buon acciaio scarseggia, e i nostri attrezzi ne hanno risentito. I minatori della Miniera Venarossa usavano picconi di ottima fattura, e immagino che qualcuno sia ancora laggiù, nelle profondità della miniera. Potresti recuperarne alcuni per me? Vedrò se riesco a riutilizzarne l'acciaio.", "Sei già <stato/stata> alla miniera?", "Oh, molto bene. Vedi come brillano? Davvero, non li fanno più come una volta.", 0x72aed2a2, 0xd649abdf, 0x8701f873, 0xbc85eca8, 0x47745ccb, "....." },
  [91733] = { "Seguendo la corrente", "Recupera Waterlogged Axe, Waterlogged Saw e Waterlogged Toolbox, trascinati dalla corrente a valle del ⟦Eastvale Logging Camp=Campo di Taglio di Vallevante⟧, poi torna da Ormin Pelford.", "Stavo riportando un carico di rifornimenti dall'emporio, ma il carro si è ribaltato e la roba è finita nel fiume! Prima che riuscissi ad afferrarla, la corrente l'aveva già trascinata a valle.\n\nCon i murloc e i lupi laggiù, per conto mio non ho nessuna speranza di recuperarla. Sembri una persona robusta. Pensi di poterla ritrovare per me?", "Hai trovato i materiali?", "Sei un po' <bagnato/bagnata>, {name}. Mi dispiace. Ma grazie per aver recuperato i materiali.", 0x5377b6c2, 0x4104ac2d, 0x5c21b1ba, 0x3a2cb041, 0xc2d835d9, "....." },
  [91736] = { "L'alambicco dell'acquavite di mele", nil, nil, "Un forte odore di mele ti brucia il naso mentre esamini il congegno.", nil, 0xdf027785, nil, nil, 0x90ed44dc, nil, ".mm.m" },
  [91738] = { "Una delizia alla mela", nil, nil, nil, nil, 0xc00668c0, nil, nil, nil, nil, ".mmmm" },
  [91740] = { "La testa di Croaky", "Consegna la Croaky's Head a Merell Ross alla ⟦Ridgepoint Tower=Torre Cresta Alta⟧.", "Senza dubbio questo murloc terrorizzava le strade della zona da tempo. Sospetti che le guardie di ronda nei dintorni vorranno sapere della sua fine.", "Sì?", "La settimana scorsa abbiamo perso due membri della guardia per colpa dei murloc, {class}. Speriamo che, ora che il loro capo è morto, potremo cominciare a ricacciarli fuori da Elwynn.", 0x9a2d8e95, 0xfefeb249, 0x70acafd1, 0x0c07a888, 0x8d54c4b8, "....." },
  [91741] = { "Un libro rosicchiato", "Restituisci il libro a fratello Paxton.", "<Uno dei coboldi ha lasciato cadere questo libro. Sembra che il coboldo abbia cercato di mangiarlo.\n\nFratello Paxton, nell'abbazia, cura una piccola biblioteca. Il libro deve venire da lì.>", "Cos'hai lì? Sembra uno dei miei libri.", "Ehi! Come mai ce l'hai tu? Dovrebbe stare sullo scaffale! Oh cielo, i coboldi mi stanno di nuovo rubando i libri. Vorranno mangiarseli!\n\nGrazie per avermi riportato il libro, ma come farò con il resto della mia collezione scomparsa?", 0xdc36fd8f, 0x60fd6d4c, 0x926272a4, 0xb5ada1fe, 0xbe3f5ca7, "....." },
  [91743] = { "Roditori birbanti", "Recupera $N1 Stolen Book dai coboldi nella ⟦Northshire Valley=Valle della Contea del Nord⟧ e riportali a fratello Paxton.", "Quei terribili coboldi si mangiano i miei libri! Devi recuperarli prima che divorino tutta la mia biblioteca.", "Hai già salvato i miei libri, {name}?!", "Grazie mille! Ecco! Prendi uno di questi manuali pratici. A me non servono.\n\nMa mancano ancora tantissimi libri. Pare che i coboldi non li mangino. E allora perché li vogliono?", 0x5ecfe128, 0xca0dec56, 0x36c2ff3a, 0x9e3c12c9, 0xcb496646, "....." },
  [91745] = { "Consulenza mineraria", "Parla con Kelsey Fargo fuori dalla ⟦Echo Ridge Mine=Miniera Cresta dell'Eco⟧, nella ⟦Northshire Valley=Valle della Contea del Nord⟧.", "Va' a parlare con la nuova apprendista minatrice, Kelsey Fargo. Lavora proprio fuori dalla miniera e probabilmente ha visto cosa combinano i coboldi. Magari, già che ci sei, può insegnarti un paio di cose sull'Estrazione.", nil, "Coboldi con dei libri? Sì, ho visto coboldi correre avanti e indietro con dei libri, urlandosi addosso. Li staranno rubando dalla biblioteca dentro l'abbazia.", 0x70de9b61, 0x928069a0, 0x595703ec, nil, 0x968f291e, "...m." },
  [91746] = { "La testa di Elmpaw", "Consegna la Elmpaw's Head a Helene Peltskinner vicino a ⟦Goldshire=Borgodoro⟧.", "Il trofeo è un ricordo impressionante della tua vittoria su Elmpaw. Un cacciatore o uno scuoiatore della zona potrebbe essere interessato a sentire la storia.", "Sì?", "Allora, hai abbattuto Elmpaw? Davvero notevole, {name}!\n\nLascia che ti dia qualcosa in cambio del tuo trofeo: conosco alcuni collezionisti che pagheranno parecchio per averlo sopra il camino, una volta che l'avrò preparato.", 0x6c96dddb, 0xa7c38435, 0x2ae37dbd, 0x0c07a888, 0xd51955d8, "....." },
  [91751] = { "Pelli di lupo grezze", "Scuoia i lupi nella ⟦Elwynn Forest=Foresta di Elwynn⟧ per ottenere $N1 Rough Wolf Pelt, poi consegnali a Helene Peltskinner vicino a ⟦Goldshire=Borgodoro⟧.", "Cerchi un'occasione per fare pratica di Scuoiatura? Di solito mio marito mi aiuta a cacciare i lupi, ma è impegnato su all'abbazia. Mi farebbe comodo una mano a raccogliere altre pelli per completare gli ordini a cui sto lavorando.", "Novità con quelle pelli di lupo?", "Ottimo lavoro con queste pelli, {class}. Hai un vero talento per la caccia.", 0xe1344efa, 0x35d88064, 0x993378eb, 0xc1490377, 0x024aeaa4, "....." },
  [91752] = { "Il quadro generale", "Recupera un sacco di libri \"illustrati\" da Shinyfinder Narf. Porta il sacco al maresciallo McBride, appena dentro l'Abbazia della Contea del Nord.", "Ogni tanto passa di qui un coboldo che urla \"Figure per Narf!\" Non so chi sia questo Narf. Forse uno dei capi coboldi in fondo alla miniera? Scommetto che ormai ha un sacco pieno di libri.\n\nVa' a prendere quei libri e portali al nostro tutore della legge, il maresciallo McBride. Faresti bene a trovare qualcuno che ti aiuti. I coboldi dentro la miniera sono molto più cattivi.", "Hai già recuperato quei libri rubati?", "Grazie per aver riportato questi libri rubati, {name}. Li restituirò subito a fratello Paxton.\n\nStai diventando <un/una> <vero/vera> <eroe/eroina> da queste parti. Ottimo lavoro!", 0xf0a9a4ae, 0x0274d4d1, 0x64d74190, 0x98bda539, 0x3c4f5b85, "....." },
  [91753] = { "Una lezione d'incantamento", "Kitta Firewind, nella ⟦Tower of Azora=Torre di Azora⟧, vuole che tu raccolga 3 Luminous Residue.\n\nPuoi ottenere il Luminous Residue disincantando le Crude Wax Effigy lasciate dai Kobold Geomancer.", "Il rigore accademico è certo essenziale nell'arte dell'incantatore, ma una base pratica può dare i suoi frutti. Considera, ad esempio, l'umile coboldo. Pur privo di un'istruzione formale, dimostra una sorta di attitudine innata per semplici trucchetti e incantamenti.\n\nProcurati alcune delle loro effigi di cera e scomponi gli incantamenti racchiusi al loro interno. Potrebbe rivelarsi illuminante.", "Che cosa hanno rivelato i tuoi studi?", "Teoria e pratica sono due facce della stessa medaglia, {name}. Ricordalo.", 0x775e64ad, 0x5706d360, 0x77774694, 0xcd72ab2a, 0x3bbdc1ae, "....." },
  [91758] = { "Segui quel coboldo!", "Parla con Tordrin Sternblade vicino alla stalla dietro l'Abbazia della Contea del Nord.", "Non hai ancora finito con quei coboldi. Kelsey ci ha appena fatto sapere che un coboldo è uscito dalla miniera con un grosso sacco di libri. Devi rintracciarlo, così potremo recuperare i libri per fratello Paxton.\n\nVa' a parlare con Tordrin Sternblade. È il nuovo istruttore dei Cacciatori, appena arrivato da ⟦Ironforge=Forgiardente⟧. Lo trovi dietro l'abbazia, vicino alla stalla. Può aiutarti a rintracciare questo coboldo ladro.", nil, "Posso aiutarti a scovare 'sta canaglia. Lascia che ti prepari qualcosa.", 0x5b4c7f86, 0xba85d0f1, 0xbabf3db2, nil, 0x0f74c33b, "...m." },
  [91772] = { "Ssst! Stiamo cacciando coboldi", "Segui le tracce dei coboldi e fai rapporto al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧, con le tue scoperte e il Kobold Tracking Kit.", "Bene. Prendi questo kit per seguire le tracce dei coboldi. Ti permetterà di rintracciare il coboldo che preoccupa il maresciallo McBride.\n\nSegui le tracce e porta quel che trovi al maresciallo Dughan, a ⟦Goldshire=Borgodoro⟧.\n\nHo idea che 'ste canaglie stiano tramando qualcosa fuori dalla ⟦Northshire=Contea del Nord⟧. Quindi ti servirà l'aiuto di Dughan.", "Hai capito dove sono diretti i coboldi?", "Che cos'è questo, {name}? Seguire le tracce dei coboldi?\n\nBe', certo che sono diretti alla Miniera Antrocupo! Quel posto è infestato di coboldi.\n\nBuon lavoro, suppongo. Mi servirà qualcuno che si occupi di quel problema.", 0xccca4f37, 0x4c6f788d, 0x88b384bf, 0x76315b25, 0x94488fef, "....." },
  [91775] = { "Restituzione dei libri", "Trova 6 Lost Book e \"Fun with Elementals\" e riportali al maresciallo Dughan.", "Mentre indaghi nella ⟦Fargodeep Mine=Miniera Antrocupo⟧, vedi se riesci a trovare qualcuno dei libri di fratello Paxton da restituire. In particolare, Paxton è molto preoccupato per un libro intitolato \"Fun with Elementals\". Pensa che perfino un coboldo potrebbe usarlo per evocare un servitore elementale. Attenzione: le profondità della miniera sono piuttosto pericolose. Faresti bene a portare degli amici.\n\nPrendi questa borsa per proteggere i libri quando li trovi!", "Hai già trovato tutti i libri?", "Plaudo alla tua diligenza, {name}. Fratello Paxton mi ha mandato una lista di libri, e tu hai trovato quasi tutti quelli scomparsi. Gli altri devono essere stati portati nella ⟦Jasperlode Mine=Miniera Venarossa⟧.\n\nPuoi tenerti quella borsa per i libri!", 0xd01af3bc, 0x88f1a8d6, 0xf4a33e50, 0x546df3d0, 0xb1a94cf2, "....." },
  [91777] = { "Libri rari", "Recupera \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\" e riportali a fratello Paxton, nell'Abbazia della Contea del Nord.", "Mancano all'appello solo due libri della lista di fratello Paxton: \"Geomancy for Curious Young Wizards\" e \"Arcane Explainer: Magical Stuff in Simple Words\".\n\nI coboldi devono averli portati nella ⟦Jasperlode Mine=Miniera Venarossa⟧. Ti prego, rintraccia quei due libri e riportali a fratello Paxton.\n\nMa temo che sarà piuttosto pericoloso. Se il coboldo \"apprendista\" evocava un elementale, chissà cosa può fare il maestro. Al posto tuo porterei qualche amico.", "Hai già trovato tutti i miei libri scomparsi?", "Oh, {name}! Grazie mille per aver salvato la mia biblioteca. Mi hai reso un servizio straordinario. Prendi una di queste ottime armi, ti prego. Erano destinate alla milizia, ma tu puoi farne un uso migliore.", 0xa9c579cb, 0xa02ab9c4, 0xa51f628c, 0xf4232bfe, 0xb2abd943, "....." },
  [91858] = { "Incidente diplomatico", "Raggiungi la ⟦The Sepulcher=Mausolea⟧, nella ⟦Silverpine Forest=Selva Pinargento⟧, e parla con Trevan Rol dei viaggiatori dell'Earthen Ring scomparsi.", "Una sfortunatissima piega degli eventi a ⟦Silverpine=Pinargento⟧ ci offre un'occasione unica per dimostrare il nostro valore agli occhi dell'Orda.\n\nDue dignitari dell'Earthen Ring sono scomparsi nella ⟦Silverpine Forest=Selva Pinargento⟧ mentre erano diretti al ⟦Tarren Mill=Mulino di Tarren⟧. Non sappiamo molto altro, ma si dice che la cosa stia diventando un vero incidente diplomatico. Se riusciamo a ritrovare gli scomparsi, potremmo ottenere la legittimità di cui abbiamo tanto bisogno.\n\nAbbiamo un uomo alla ⟦The Sepulcher=Mausolea⟧, Trevan Rol. Va' laggiù e parla con lui.", nil, "Ti ha mandato Danitha? Be', allora so già perché sei qui. Sei <capitato/capitata> in un maledetto pasticcio, {class}.", 0x860aa6df, 0x49857281, 0x51cda335, nil, 0xe436fee9, "...m." },
  [91859] = { "Una strana coppia", "Parla con la Guardia della Morte Baldren dei misteriosi viaggiatori dell'Earthen Ring passati di recente per la ⟦The Sepulcher=Mausolea⟧.", "Vado dritto al punto: questi \"dignitari\" non sono diplomatici qualunque. Uno era un Tauren. Niente di strano per l'Earthen Ring, ma l'altro, e stenterai a crederci, era un elfo. Un *alto* elfo. Erano incappucciati, ma ho già visto dei quel'dorei e scommetterei il mio mignolo buono che è quello che ho visto.\n\nPerché un elfo accompagnava un Tauren attraverso il territorio dell'Orda? Be', ne so quanto te. Questo è tutto ciò che so, quindi ti suggerisco di parlare con la Guardia della Morte Baldren, vicino all'ingresso del paese.", nil, "Voi paladini non mi state granché simpatici, ma devo dire che il tuo tempismo è impeccabile. Meglio fortunati che bravi, no?", 0x81390067, 0x9840d880, 0x5b66726d, nil, 0x4666daba, "...m." },
  [91860] = { "Un triste destino", "Indaga sull'⟦Fenris Isle=Isola di Fenris⟧, a est, e scopri che fine ha fatto il gruppo di viaggiatori dell'Earthen Ring.", "Ieri notte, durante la ronda, ho visto un gruppo di gnoll gettare un corpo molto grosso su una pira sulle rive dell'⟦Fenris Isle=Isola di Fenris⟧. Non ho visto né un elfo né cadaveri più piccoli, ma direi che per loro non promette niente di buono.\n\nSe sei <coraggioso/coraggiosa> o <stupido/stupida>, sei liber<o/a> di precipitarti sull'⟦Fenris Isle=Isola di Fenris⟧ per saperne di più, ma secondo me è un bel lavoro per trovare un elfo spocchioso che probabilmente è morto da un pezzo.\n\nLo so che voi paladini adorate giurare e abbracciare cause perse, ma questa non ne vale la pena. Fidati.", nil, "<Il cadavere davanti a te era senza dubbio di un Tauren, e si vede che è stato rosicchiato a lungo prima di essere gettato sulla pira. Però non vedi traccia dell'elfa che ti hanno descritto. Forse è ancora viva da qualche parte, più in profondità nella fortezza vicina?\n\nSarà pericoloso, ma c'è un solo modo per scoprirlo con certezza.>", 0x08dbafc9, 0x269e6b75, 0x06c5da17, nil, 0x0c72db2b, "...m." },
  [91861] = { "Dentro ⟦Fenris Keep=Forte Fenris⟧", "Indaga a ⟦Fenris Keep=Forte Fenris⟧, a nord, e cerca di ritrovare il membro scomparso del gruppo dell'Earthen Ring.", "<Il fatto che tu abbia trovato un solo corpo è un segno di speranza. Forse l'alta elfa descritta da Trevan e Hadrec è ancora viva da qualche parte, più in profondità nella fortezza vicina?>", nil, "Sei uno dei Reietti, vero? Puoi aiutarmi a liberarmi?\n\nTemo di avere poco tempo. Ti prego, sbrigati!", 0x52a5ca6c, 0x05375492, 0xfcb8e7e8, nil, 0xc4755d7d, "...m." },
  [91862] = { nil, "Recupera la Fenris Isle Key dai Rot Hide Gnoll e usala per liberare Lumina Windsinger.", "Quel'dorei? No, non sono una \"quel'dorei\". Sono Lumina Windsinger e sono shen'dorei. Una dei Windshaper Skyborne.\n\nSono venuta in queste terre come ospite dell'Earthen Ring. Il mio compagno Banon e io stavamo attraversando ⟦Silverpine=Pinargento⟧ per raggiungere gli ⟦Arathi Highlands=Altopiani d'Arathi⟧, dove volevamo studiare le convergenze elementali. Evidentemente non ci siamo riusciti.\n\nMa ora non abbiamo tempo per questo. Uccidi gli gnoll qui vicino. Recupera la chiave di questa gabbia e liberami. Ti racconterò il resto quando saremo al sicuro.", "Gli gnoll sono le seconde creature peggiori che abbia incontrato finora su Azeroth.", "Grazie, {class}. Purtroppo non siamo ancora fuori pericolo.", 0x8615ca23, 0x9d3e70b4, 0x1c33efa2, 0xd342e852, 0x59d83bf0, "e...." },
  [91899] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91900] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91901] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91904] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "Grazie per il tuo impegno, {name}. Ultimamente c'è stata un'ondata di banditi e ladri che intercettano le rotte commerciali. Se trovi altre casse in giro, portale qui e al resto penseremo noi.\n\nEcco il tuo compenso.", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91905] = { "Una ⟦Sealed Crate=Cassa Sigillata⟧", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
