  [91920] = { "Occhi selvaggi", "Raccogli 3 Occhio di Murloc e portali allo speziale Renferrel, alla ⟦Sepulcher=Mausolea⟧.", "Non oserei mai mettere in dubbio l'efficacia delle formule dello speziale Renferrel, ma mentirei se dicessi che la pozione ha fatto una qualche differenza.\n\nLungo la riva del Lago Lordamere c'è uno sciame di murloc e, cosa degna di nota, i murloc hanno gli occhi. Sospetto che la voglia dello speziale di provare cose nuove sia soffocata dalla sua recente ossessione per i cuori. Portagliene qualcuno.\n\nSe devo scegliere tra morire inevitabilmente una seconda volta o farmi uccidere da Renferrel per aver messo in dubbio i suoi metodi, scelgo la seconda.", "Oh. Sei tornat<o/a>?", "La pozione non ha funzionato? Certo che non ha funzionato. Mi hai portato cuori insufficienti. La ricetta ne richiede chiaramente sei. Tu ne hai portati tre.\n\nTuttavia, ammetto che finora non avevo considerato possibili usi per le parti di murloc...\n\n<Renferrel prende gli occhi.>\n\nPosso permettermi di sacrificare qualcuno dei miei cuori per restituire le forze al tuo Inseguitore della Morte.", 0x44275ed7, 0xd4c23f40, 0x9795c646, 0x45e80936, 0x10bbdd28, "....." },
  [91921] = { "Ritorno da Quinn (di nuovo)", "Porta la pozione di Quinn a Quinn Yorick, all'Ivar Patch, a nord della ⟦Sepulcher=Mausolea⟧.", "Ecco la nuova pozione per aiutare Quinn a riprendersi, preparata con l'amore estratto da sei cuori interi.\n\nOra, ti prego, scusami, prima che la tua presenza renda necessarie altre scartoffie.", "Sei tornat<o/a>! Cominciavo a rassegnarmi a degenerare in un ghoul.", "<Quinn prende la pozione e la beve.>\n\nSì, sento che fa effetto. Presto potrò rimettermi in viaggio.\n\nMi hai fatto un grande favore, {name}.", 0x641834db, 0xed042c3f, 0x0c746cd7, 0x1411f25f, 0xc5dd8287, "....." },
})
